    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });

  assert.equal(result2024.ok, true);
  assert.equal(result2025.ok, true);

  const existing = [];
  const issue2024 = issueInvoice(result2024.value, existing);
  existing.push(issue2024.value.number);

  const issue2025 = issueInvoice(result2025.value, existing);

  assert.equal(issue2024.value.number, 'INV-2024-0001');
  assert.equal(issue2025.value.number, 'INV-2025-0001');
});

